<template>
  <Card :class="['border-l-4', borderClass]">
    <CardHeader class="pb-3">
      <div class="flex items-center gap-2">
        <component :is="headingIcon" :class="['size-5', headingIconClass]" />
        <CardTitle class="text-base">{{ headingText }}</CardTitle>
      </div>
    </CardHeader>
    <CardContent>
      <ul v-if="bullets.length" class="flex flex-col gap-2.5">
        <li v-for="bullet in bullets" :key="bullet.key" class="flex items-start gap-3">
          <span
            :class="[
              'mt-0.5 flex size-7 shrink-0 items-center justify-center rounded-full',
              bulletBgClass(bullet.severity),
            ]"
          >
            <component :is="bullet.icon" :class="['size-4', bulletIconClass(bullet.severity)]" />
          </span>
          <p class="text-sm leading-snug pt-1">{{ bullet.headline }}</p>
        </li>
      </ul>
      <p v-else class="text-sm text-muted-foreground">No fraud signals tripped the algorithm's thresholds.</p>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { CircleCheckIcon, TriangleAlertIcon } from 'lucide-vue-next';
import type { RenderedReport } from '~/client';
import type { FraudSeverity } from '~/constants/reports/fraudReportCards';
import { getFraudSeverityStyle } from '~/constants/reports/fraudReportCards';
import { renderVerdictBullets } from '~/utils/reports/fraudVerdictBullets';

interface Props {
  stats: RenderedReport;
}
const props = defineProps<Props>();

const bullets = computed(() => renderVerdictBullets(props.stats));

const topSeverity = computed<FraudSeverity>(() => bullets.value[0]?.severity ?? 'normal');

const headingText = computed(() => (bullets.value.length ? 'Top concerns' : 'Nothing unusual detected'));
const headingIcon = computed(() => (bullets.value.length ? TriangleAlertIcon : CircleCheckIcon));
const headingIconClass = computed(() => (bullets.value.length ? 'text-orange-600' : 'text-green-600'));

const borderClass = computed(() => getFraudSeverityStyle(topSeverity.value).borderClass);

function bulletBgClass(severity: FraudSeverity): string {
  return getFraudSeverityStyle(severity).bulletBgClass;
}
function bulletIconClass(severity: FraudSeverity): string {
  return getFraudSeverityStyle(severity).bulletTextClass;
}
</script>
