import { confirmReport } from '~/client';

export const useConfirmReport = defineMutation(() => {
  const { mutateAsync: confirmReportMutation, asyncStatus } = useMutation({
    mutation: (reportId: string) =>
      confirmReport({
        composable: '$fetch',
        path: { report_id: reportId },
      }),
    onSuccess: async (_, reportId) => {
      showToastSuccess('Report confirmed successfully.');
      const queryCache = useQueryCache();
      await queryCache.invalidateQueries({ key: ['report-details', reportId] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    confirmReportMutation,
    isConfirmingReport: computed(() => asyncStatus.value === 'loading'),
  };
});
