<template>
  <Card>
    <CardContent class="flex flex-col items-center justify-center gap-2 py-10 text-center">
      <component :is="copy.icon" class="w-8 h-8" :class="copy.iconClass" />
      <h3 class="text-base font-semibold">{{ copy.title }}</h3>
      <p class="text-sm text-muted-foreground max-w-md">{{ copy.description }}</p>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { ClockIcon, OctagonAlertIcon, MinusCircleIcon, type LucideIcon } from 'lucide-vue-next';
import type { ViewDataState } from '~/client';

interface Props {
  state: Exclude<ViewDataState, 'ready'>;
}
const props = defineProps<Props>();

const stateCopy: Record<Props['state'], { title: string; description: string; icon: LucideIcon; iconClass: string }> = {
  pending: {
    title: 'Report data is being prepared',
    description:
      'The interactive view is still being generated. This usually takes a few minutes after the shift ends.',
    icon: ClockIcon,
    iconClass: 'stroke-blue-500',
  },
  failed: {
    title: 'Interactive view unavailable',
    description: 'We could not generate the interactive view for this report. The PDF below is still available.',
    icon: OctagonAlertIcon,
    iconClass: 'stroke-destructive',
  },
  skipped: {
    title: 'Interactive view skipped',
    description: 'This report did not meet the threshold for full fraud detection processing.',
    icon: MinusCircleIcon,
    iconClass: 'stroke-muted-foreground',
  },
};

const copy = computed(() => stateCopy[props.state]);
</script>
