import { getCanvassingFraudReportViewData, type GetCanvassingFraudReportViewDataResponse } from '~/client';

export function useReportViewDataQuery(
  reportId: Ref<string | undefined>,
  enabled?: Ref<boolean>,
  simplified?: Ref<boolean>
) {
  return useQuery({
    key: () => ['report-view-data', reportId.value ?? '', simplified?.value ?? true],
    query: (): Promise<GetCanvassingFraudReportViewDataResponse> =>
      getCanvassingFraudReportViewData({
        composable: '$fetch',
        path: { report_id: reportId.value as string },
        query: simplified !== undefined ? { simplified: simplified.value } : undefined,
      }),
    enabled: () => Boolean(reportId.value) && (enabled ? enabled.value : true),
    staleTime: 60_000,
  });
}
