<template>
  <div class="flex flex-col gap-2">
    <div class="flex items-center justify-between text-xs font-semibold uppercase tracking-wide text-muted-foreground">
      <span>Flagged interactions ({{ items.length }})</span>
      <div class="flex items-center gap-1 normal-case tracking-normal">
        <span class="text-muted-foreground font-medium">Sort by</span>
        <button
          data-testid="sort-severity"
          type="button"
          :class="[
            'rounded-md px-2 py-0.5 text-xs font-semibold border',
            sortMode === 'severity'
              ? 'bg-foreground text-background border-foreground'
              : 'bg-background text-foreground border-border',
          ]"
          @click="sortMode = 'severity'"
        >
          Severity
        </button>
        <button
          data-testid="sort-time"
          type="button"
          :class="[
            'rounded-md px-2 py-0.5 text-xs font-semibold border',
            sortMode === 'time'
              ? 'bg-foreground text-background border-foreground'
              : 'bg-background text-foreground border-border',
          ]"
          @click="sortMode = 'time'"
        >
          Time
        </button>
      </div>
    </div>

    <div class="grid grid-cols-1 md:grid-cols-2 gap-2 max-h-80 overflow-auto pr-1">
      <button
        v-for="item in sortedItems"
        :key="item.id ?? `noid-${item.ts}-${item.location?.latitude}-${item.location?.longitude}`"
        data-testid="engagement-flag-row"
        :data-selected="item.id === selectedInteractionId ? 'true' : 'false'"
        type="button"
        :class="[
          'grid grid-cols-[5px_1fr_auto] gap-2 items-center text-left p-2.5 rounded-md border bg-card hover:bg-muted/40',
          item.id === selectedInteractionId ? 'ring-2 ring-red-200 border-red-200 bg-background' : 'border-border',
        ]"
        @click="onRowClick(item)"
      >
        <span :class="['self-stretch rounded-sm', getFraudSeverityStyle(item.fraud?.severity).dotBgClass]" />
        <div class="min-w-0">
          <div class="text-sm font-semibold flex items-center gap-1.5">
            <span>#{{ displayNumber(item) }}</span>
            <span class="text-muted-foreground font-normal">·</span>
            <span class="text-muted-foreground font-normal">{{ formatTimeOfDay(item.ts) }}</span>
            <span
              v-if="!isOnMap(item)"
              class="rounded px-1.5 py-0.5 text-[10px] font-semibold bg-muted text-muted-foreground"
              title="No GPS location for this interaction — cannot be shown on the map"
            >
              Off map
            </span>
            <span
              v-if="item.canvasser_distance_m != null"
              data-testid="gap-distance"
              class="rounded px-1.5 py-0.5 text-[10px] font-semibold bg-red-50 text-red-700"
              title="Distance from the canvasser to the voter's house at the interaction"
            >
              ~{{ Math.round(item.canvasser_distance_m) }} m away
            </span>
          </div>
          <div class="text-xs text-muted-foreground mt-0.5">"{{ formatResponseLabel(item.response) }}"</div>
          <div v-if="item.fraud" class="flex flex-wrap gap-1 mt-1.5">
            <span
              v-for="reason in item.fraud.reasons"
              :key="reason.code"
              data-testid="reason-chip"
              :class="[
                'text-[10px] font-semibold px-1.5 py-0.5 rounded border',
                fraudSeverityConfig[reason.severity].chipClass,
              ]"
            >
              {{ reason.label }}
            </span>
          </div>
          <div v-if="item.app_flag_reasons?.length" class="flex flex-wrap gap-1 mt-1.5">
            <span
              v-for="reason in item.app_flag_reasons"
              :key="reason"
              data-testid="app-flag-chip"
              :class="APP_FLAG_REASON_CHIP_CLASS"
            >
              {{ reason }}
            </span>
          </div>
        </div>
        <span
          v-if="isOnMap(item)"
          class="text-muted-foreground text-sm self-start pt-0.5"
          aria-hidden="true"
          title="Show on map"
          >↑</span
        >
      </button>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { InteractionPointView } from '~/client';
import { fraudSeverityConfig, getFraudSeverityStyle } from '~/constants/reports/fraudReportCards';
import { formatResponseLabel, formatTimeOfDay } from '~/utils/canvassing/format';
import { isValidLatLng } from '~/utils/canvassing/coords';
import { sortFlaggedInteractions, type FlaggedInteractionsSortMode } from '~/utils/canvassing/flaggedInteractionsSort';
import {
  APP_FLAG_REASON_CHIP_CLASS,
  interactionMatchesAppFlag,
  type RowFlagKey,
} from '~/constants/workshifts/canvassingAppStatsConfig';

interface Props {
  interactions: InteractionPointView[];
  selectedInteractionId: number | null;
  // Active app-flag drill-down from the report's flag tiles. Null = no filter.
  flagFilter?: RowFlagKey | null;
}
const props = withDefaults(defineProps<Props>(), { flagFilter: null });

const emit = defineEmits<{
  'update:selectedInteractionId': [id: number | null];
  'request-focus-map': [];
}>();

const sortMode = ref<FlaggedInteractionsSortMode>('severity');

const items = computed(() => props.interactions.filter((i) => interactionMatchesAppFlag(i, props.flagFilter)));
const sortedItems = computed(() => sortFlaggedInteractions(items.value, sortMode.value));

// 1-based number derived from the backend `id`, matching the map marker labels.
function displayNumber(item: InteractionPointView): string {
  return item.id != null ? String(item.id + 1) : '?';
}

// An interaction can be shown on the map only if it has valid coordinates.
function isOnMap(item: InteractionPointView): boolean {
  return isValidLatLng(item.location?.latitude, item.location?.longitude);
}

function onRowClick(item: InteractionPointView) {
  emit('update:selectedInteractionId', item.id ?? null);
  // Only ask the parent to scroll/focus the map for interactions that are
  // actually on it — off-map (no-GPS) rows have nothing to focus.
  if (isOnMap(item)) emit('request-focus-map');
}
</script>
