<template>
  <Popover>
    <PopoverTrigger as-child>
      <button
        type="button"
        :aria-label="ariaLabel"
        class="inline-flex items-center text-muted-foreground hover:text-foreground transition-colors"
      >
        <InfoIcon :class="['shrink-0', sizeClass]" />
      </button>
    </PopoverTrigger>
    <PopoverContent :class="['text-sm leading-snug', widthClass]">
      <slot>{{ description }}</slot>
    </PopoverContent>
  </Popover>
</template>

<script setup lang="ts">
import { Popover, PopoverContent, PopoverTrigger } from '~/components/ui/popover';
import { InfoIcon } from 'lucide-vue-next';

interface Props {
  description?: string;
  ariaLabel?: string;
  size?: 'sm' | 'md';
  width?: 'sm' | 'md' | 'lg';
}
const props = withDefaults(defineProps<Props>(), {
  description: '',
  ariaLabel: 'More info',
  size: 'sm',
  width: 'md',
});

const sizeClass = computed(() => (props.size === 'md' ? 'h-4 w-4' : 'h-3.5 w-3.5'));
const widthClass = computed(() => (props.width === 'lg' ? 'w-96' : props.width === 'sm' ? 'w-56' : 'w-72'));
</script>
