<template>
  <div class="flex flex-col gap-1.5">
    <div class="flex flex-wrap items-center gap-x-3 gap-y-1 text-[10px] uppercase tracking-wide text-muted-foreground">
      <span v-for="zone in zones" :key="`legend-${zone.label}`" class="flex items-center gap-1.5">
        <span :class="['inline-block size-2.5 rounded-sm', zone.bgClass]" />
        <span>{{ zone.label }}</span>
      </span>
    </div>

    <div class="relative h-5">
      <div class="absolute inset-0 flex w-full overflow-hidden rounded-md">
        <div
          v-for="zone in zones"
          :key="zone.label"
          :class="['h-full', zone.bgClass]"
          :style="{ width: `${zone.widthPct}%` }"
        />
      </div>

      <div
        v-if="topPct !== null"
        class="absolute top-0 h-full w-0.5 -translate-x-1/2 bg-foreground/90"
        :style="{ left: `${topPct}%` }"
        :aria-label="`Top speed ${safeTop.toFixed(1)} m/s`"
      />

      <div
        v-if="avgPct !== null"
        class="absolute top-0 h-full w-0.5 -translate-x-1/2 bg-foreground/50"
        :style="{ left: `${avgPct}%` }"
        :aria-label="`Average speed ${safeAvg.toFixed(1)} m/s`"
      />
    </div>

    <div class="relative h-4 text-[11px] tabular-nums">
      <span
        v-if="avgPct !== null && !valueLabelsCollide"
        class="absolute top-0 -translate-x-1/2 whitespace-nowrap text-foreground/70"
        :style="{ left: `${avgPct}%` }"
      >
        avg {{ safeAvg.toFixed(1) }}
      </span>
      <span
        v-if="topPct !== null && !valueLabelsCollide"
        class="absolute top-0 -translate-x-1/2 whitespace-nowrap font-medium"
        :style="{ left: `${topPct}%` }"
      >
        top {{ safeTop.toFixed(1) }} m/s
      </span>
      <span
        v-if="valueLabelsCollide"
        class="absolute top-0 -translate-x-1/2 whitespace-nowrap font-medium"
        :style="{ left: `${topPct}%` }"
      >
        avg {{ safeAvg.toFixed(1) }} · top {{ safeTop.toFixed(1) }} m/s
      </span>
    </div>
  </div>
</template>

<script setup lang="ts">
interface Props {
  avg: number;
  top: number;
}
const props = defineProps<Props>();

const WALKING_MAX = 2;
const RUNNING_MAX = 5.5;
const VALUE_LABEL_COLLISION_PCT = 12;
const FALLBACK_SCALE_MAX = 8;

const scaleMax = computed(() => {
  const t = props.top;
  if (!Number.isFinite(t) || t <= 0) return FALLBACK_SCALE_MAX;
  return Math.max(FALLBACK_SCALE_MAX, Math.ceil(t * 1.15));
});

const safeAvg = computed(() => (Number.isFinite(props.avg) ? props.avg : 0));
const safeTop = computed(() => (Number.isFinite(props.top) ? props.top : 0));

interface Zone {
  label: string;
  start: number;
  end: number;
  bgClass: string;
}

const zones = computed(() => {
  const max = scaleMax.value;
  const raw: Zone[] = [
    { label: 'walking', start: 0, end: Math.min(WALKING_MAX, max), bgClass: 'bg-green-200' },
    { label: 'running', start: WALKING_MAX, end: Math.min(RUNNING_MAX, max), bgClass: 'bg-yellow-200' },
    { label: 'vehicle', start: RUNNING_MAX, end: max, bgClass: 'bg-red-200' },
  ];
  return raw
    .filter((z) => z.end > z.start)
    .map((z) => {
      const widthPct = ((z.end - z.start) / max) * 100;
      return { ...z, widthPct };
    });
});

function clampPct(value: number): number | null {
  if (!Number.isFinite(value) || value < 0) return null;
  const pct = (value / scaleMax.value) * 100;
  return Math.max(0, Math.min(100, pct));
}

const avgPct = computed(() => clampPct(props.avg));
const topPct = computed(() => clampPct(props.top));

const valueLabelsCollide = computed(() => {
  if (avgPct.value === null || topPct.value === null) return false;
  return Math.abs(topPct.value - avgPct.value) < VALUE_LABEL_COLLISION_PCT;
});
</script>
