import {
  GaugeIcon,
  MapPinIcon,
  MessageSquareIcon,
  PauseIcon,
  RotateCwIcon,
  SmartphoneIcon,
  ZapIcon,
} from 'lucide-vue-next';
import type { Component } from 'vue';
import type { RenderedReport, RiskLevel, VerdictObservation } from '~/client';
import { fraudSeverityConfig, type FraudSeverity } from '~/constants/reports/fraudReportCards';

type ObservationKey = VerdictObservation['key'];

export interface VerdictBullet {
  key: ObservationKey | `app_flag:${number}`;
  severity: FraudSeverity;
  icon: Component;
  headline: string;
}

const OBSERVATION_RENDER: Record<ObservationKey, { icon: Component; headline: (mag: number) => string }> = {
  simulated_location: {
    icon: MapPinIcon,
    headline: () => 'Location signals look spoofed.',
  },
  gps_moved_phone_still: {
    icon: SmartphoneIcon,
    headline: (mag) => `GPS moved while the phone stayed still in ${mag.toFixed(0)}% of the route.`,
  },
  phone_moved_gps_still: {
    icon: SmartphoneIcon,
    headline: (mag) => `Phone moved while GPS was frozen in ${mag.toFixed(0)}% of the route.`,
  },
  speed_mismatch: {
    icon: ZapIcon,
    headline: (mag) => `GPS and phone sensors disagreed on speed in ${mag.toFixed(0)}% of the route.`,
  },
  high_acceleration: {
    icon: GaugeIcon,
    headline: (mag) => `Phone hit impossible acceleration bursts in ${mag.toFixed(0)}% of the route.`,
  },
  fast_spinning: {
    icon: RotateCwIcon,
    headline: (mag) => `Phone was spinning unnaturally fast in ${mag.toFixed(0)}% of the route.`,
  },
  untracked_time: {
    icon: MapPinIcon,
    headline: (mag) => `${mag.toFixed(0)}% of the shift had no GPS coverage.`,
  },
  long_pauses: {
    icon: PauseIcon,
    headline: (mag) => `Spent ${mag.toFixed(0)}% of the shift on pause.`,
  },
  suspected_interactions: {
    icon: MessageSquareIcon,
    headline: (mag) => `${mag.toFixed(0)}% of interactions were flagged as suspicious.`,
  },
  interactions_without_gps: {
    icon: MessageSquareIcon,
    headline: (mag) => `${mag.toFixed(0)}% of interactions were logged with no GPS evidence.`,
  },
  phantom_pause: {
    icon: PauseIcon,
    headline: (mag) =>
      `A ${mag.toFixed(0)}-minute break was recorded, but the device kept tracking and interactions continued — likely an accidental Break tap.`,
  },
  interactions_during_break: {
    icon: MessageSquareIcon,
    headline: (mag) => `${mag.toFixed(0)} interaction${mag === 1 ? '' : 's'} logged during a recorded break.`,
  },
};

const APP_RISK_TO_SEVERITY: Partial<Record<RiskLevel, FraudSeverity>> = {
  critical: 'critical',
  high: 'concerning',
  medium: 'notable',
};

export function renderVerdictBullets(stats: RenderedReport, limit = 5): VerdictBullet[] {
  const sensor: VerdictBullet[] = [];
  for (const obs of stats.verdict_observations ?? []) {
    const render = OBSERVATION_RENDER[obs.key];
    if (!render) continue;
    sensor.push({ key: obs.key, severity: obs.severity, icon: render.icon, headline: render.headline(obs.magnitude) });
  }

  const appFlag: VerdictBullet[] = [];
  (stats.app_flags?.risk_reasons ?? []).forEach((reason, i) => {
    const severity = APP_RISK_TO_SEVERITY[reason.level];
    if (!severity) return;
    appFlag.push({ key: `app_flag:${i}`, severity, icon: SmartphoneIcon, headline: reason.text });
  });

  return [...sensor, ...appFlag]
    .sort((a, b) => fraudSeverityConfig[b.severity].rank - fraudSeverityConfig[a.severity].rank)
    .slice(0, limit);
}
