<template>
  <Card v-if="entries.length">
    <CardHeader>
      <CardTitle>Motion Sensor Plots</CardTitle>
    </CardHeader>
    <CardContent>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div v-for="entry in entries" :key="entry.key" class="flex flex-col gap-1">
          <p class="text-sm font-medium">{{ entry.label }}</p>
          <a :href="entry.url" target="_blank" rel="noopener noreferrer" class="block">
            <img :src="entry.url" :alt="entry.alt" class="w-full h-auto rounded-sm border" />
          </a>
        </div>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
interface Props {
  motionSensorPlotUrls: Record<string, string>;
}
const props = defineProps<Props>();

const MOTION_PLOT_LABELS: Record<string, { label: string; alt: string }> = {
  accel_raw: { label: 'Accelerometer (raw)', alt: 'Raw accelerometer time series for the shift' },
  accel_x_raw: { label: 'Accelerometer X (raw)', alt: 'Raw accelerometer X-axis signal for the shift' },
  accel_y_raw: { label: 'Accelerometer Y (raw)', alt: 'Raw accelerometer Y-axis signal for the shift' },
  accel_z_raw: { label: 'Accelerometer Z (raw)', alt: 'Raw accelerometer Z-axis signal for the shift' },
  accel_magnitude: { label: 'Accelerometer Magnitude', alt: 'Combined accelerometer magnitude over time' },
  gyro_raw: { label: 'Gyroscope (raw)', alt: 'Raw gyroscope time series for the shift' },
  gyro_x_raw: { label: 'Gyroscope X (raw)', alt: 'Raw gyroscope X-axis signal for the shift' },
  gyro_y_raw: { label: 'Gyroscope Y (raw)', alt: 'Raw gyroscope Y-axis signal for the shift' },
  gyro_z_raw: { label: 'Gyroscope Z (raw)', alt: 'Raw gyroscope Z-axis signal for the shift' },
  gyro_magnitude: { label: 'Gyroscope Magnitude', alt: 'Combined gyroscope magnitude over time' },
  magnetometer_raw: { label: 'Magnetometer (raw)', alt: 'Raw magnetometer signal for the shift' },
  pressure_raw: { label: 'Barometric Pressure', alt: 'Barometric pressure readings for the shift' },
};

function humanize(key: string): { label: string; alt: string } {
  const known = MOTION_PLOT_LABELS[key];
  if (known) return known;
  const label = key.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
  return { label, alt: `${label} plot` };
}

const entries = computed(() =>
  Object.entries(props.motionSensorPlotUrls)
    .filter(([, url]) => Boolean(url))
    .map(([key, url]) => {
      const { label, alt } = humanize(key);
      return { key, url, label, alt };
    })
);
</script>
