<template>
  <section class="flex flex-col gap-3">
    <div class="flex items-center justify-between">
      <h3 class="text-base font-semibold">Fraud Flags</h3>
      <span
        v-if="hasAnyFlag"
        class="text-sm font-semibold tabular-nums"
        :class="flaggedRows > 0 ? 'text-red-600 dark:text-red-500' : 'text-muted-foreground'"
      >
        {{ flaggedRows }} flagged
      </span>
    </div>

    <p v-if="!hasAnyFlag" class="text-sm text-muted-foreground">No fraud flags detected.</p>

    <template v-else>
      <div v-if="hasChips" class="flex flex-wrap gap-2">
        <span v-if="flags.high_dph_outlier" :class="chipClass">High DPH Outlier</span>
        <span v-if="flags.low_dph_outlier" :class="chipClass">Low DPH Outlier</span>
        <span v-if="flags.low_survey_rate" :class="chipClass">Low Survey Rate</span>
        <span
          v-for="(streak, i) in allStreaks"
          :key="`streak-${i}`"
          :class="STREAK_SEVERITY_BADGE_CLASS[streak.severity]"
          class="rounded-full px-3 py-1 text-xs font-medium"
        >
          {{ formatResponseStreak(streak) }}
        </span>
      </div>

      <div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
        <Card
          v-for="tile in decoratedTiles"
          :key="tile.key"
          :class="[
            'px-4 py-3',
            tile.value > 0 ? 'border-l-4 border-l-red-500' : '',
            isInteractive(tile)
              ? 'cursor-pointer text-left transition-colors hover:bg-muted/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500'
              : '',
            isActiveTile(tile) ? 'ring-2 ring-red-500 bg-red-50 dark:bg-red-950/30' : '',
          ]"
          :role="isInteractive(tile) ? 'button' : undefined"
          :tabindex="isInteractive(tile) ? 0 : undefined"
          :aria-pressed="isInteractive(tile) ? isActiveTile(tile) : undefined"
          :aria-label="isInteractive(tile) ? `Show ${tile.label} interactions` : undefined"
          :title="isInteractive(tile) ? `Show ${tile.label} interactions` : tile.description"
          @click="onTileClick(tile)"
          @keydown.enter.prevent="onTileClick(tile)"
          @keydown.space.prevent="onTileClick(tile)"
        >
          <p class="text-xs text-muted-foreground">{{ tile.label }}</p>
          <p :class="['text-lg font-semibold tabular-nums', tile.value > 0 ? 'text-red-600 dark:text-red-500' : '']">
            {{ tile.value }}
          </p>
        </Card>
      </div>
    </template>
  </section>
</template>

<script setup lang="ts">
import type { CanvassingAppFlags, ResponseStreak } from '~/client';
import {
  FLAG_COUNT_TILES,
  formatResponseStreak,
  STREAK_SEVERITY_BADGE_CLASS,
  type RowFlagKey,
} from '~/constants/workshifts/canvassingAppStatsConfig';

interface Props {
  flags: CanvassingAppFlags;
  // When `selectable`, non-zero count tiles become buttons that drill into the
  // matching interactions (parent binds `selectedFlag` via v-model). Left off on
  // the statistics tab, where the tiles are a static summary.
  selectable?: boolean;
  selectedFlag?: RowFlagKey | null;
}
const props = withDefaults(defineProps<Props>(), { selectable: false, selectedFlag: null });

const emit = defineEmits<{ 'update:selectedFlag': [flag: RowFlagKey | null] }>();

const chipClass =
  'rounded-full bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400 px-3 py-1 text-xs font-medium';

const flaggedRows = computed(() => props.flags.flagged_rows ?? 0);

const decoratedTiles = computed(() => FLAG_COUNT_TILES.map((t) => ({ ...t, value: t.get(props.flags) })));

type DecoratedTile = (typeof decoratedTiles.value)[number];

// A tile is interactive only when the parent enabled selection and the tile has
// interactions behind it (count > 0).
function isInteractive(tile: DecoratedTile): boolean {
  return props.selectable && tile.value > 0;
}

function isActiveTile(tile: DecoratedTile): boolean {
  return props.selectedFlag !== null && tile.rowFlag === props.selectedFlag;
}

// Toggle: clicking the active flag clears the filter; clicking another switches.
function onTileClick(tile: DecoratedTile): void {
  if (!isInteractive(tile)) return;
  emit('update:selectedFlag', isActiveTile(tile) ? null : tile.rowFlag);
}

const allStreaks = computed<ResponseStreak[]>(() => [
  ...(props.flags.no_answer_streaks ?? []),
  ...(props.flags.survey_streaks ?? []),
]);

const hasChips = computed(
  () =>
    Boolean(props.flags.high_dph_outlier) ||
    Boolean(props.flags.low_dph_outlier) ||
    Boolean(props.flags.low_survey_rate) ||
    allStreaks.value.length > 0
);

const hasAnyFlag = computed(() => decoratedTiles.value.some((t) => t.value > 0) || hasChips.value);
</script>
