<template>
  <div class="flex flex-col gap-1.5">
    <div class="flex items-center gap-2">
      <span class="text-sm">{{ title }}</span>
      <InfoTooltip v-if="description" :description="description" :aria-label="`About: ${title}`" />
      <span class="ml-auto text-sm font-medium tabular-nums">{{ formattedValue }}</span>
    </div>
    <div class="flex gap-1">
      <div
        v-for="block in blocks"
        :key="block.idx"
        class="h-2.5 flex-1 rounded-full border transition-colors"
        :style="{
          backgroundColor: block.fill ? block.fillColor : 'transparent',
          borderColor: block.fill ? block.fillColor : block.hollowColor,
        }"
      />
    </div>
    <div class="relative h-3 text-[10px] uppercase tracking-wide text-muted-foreground">
      <span class="absolute top-0 -translate-x-1/2" style="left: 16.67%">Low</span>
      <span class="absolute top-0 -translate-x-1/2" style="left: 50%">Medium</span>
      <span class="absolute top-0 -translate-x-1/2" style="left: 83.33%">High</span>
    </div>
  </div>
</template>

<script setup lang="ts">
interface Props {
  title: string;
  description?: string;
  value: number | null | undefined;
  normalThresholdPct?: number;
  criticalThresholdPct?: number;
}
const props = withDefaults(defineProps<Props>(), {
  description: '',
  normalThresholdPct: 20,
  criticalThresholdPct: 80,
});

// 21 blocks divides cleanly into three 7-block tiers (low / medium / high). Each
// tier owns a third of the bar width so the visible LOW/MEDIUM/HIGH zones match
// the colour thresholds — a value that has tripped the notable threshold lands
// past the LOW zone visually, not at its start.
const BLOCKS_PER_TIER = 7;
const BLOCK_COUNT = BLOCKS_PER_TIER * 3;
const LOW_END_BLOCK = BLOCKS_PER_TIER;
const MEDIUM_END_BLOCK = BLOCKS_PER_TIER * 2;

const GREEN_FILL = '#16a34a';
const GREEN_HOLLOW = '#a8dcc1';
const AMBER_FILL = '#f59e0b';
const AMBER_HOLLOW = '#f3d6a3';
const RED_FILL = '#ef4444';
const RED_HOLLOW = '#f1b5b5';

interface Block {
  idx: number;
  fill: boolean;
  fillColor: string;
  hollowColor: string;
}

const clampedPct = computed(() => {
  if (typeof props.value !== 'number' || Number.isNaN(props.value)) return 0;
  return Math.max(0, Math.min(100, props.value));
});

// Map the raw value to a block count via a piecewise linear scale: each tier
// (0 → normal, normal → critical, critical → 100) consumes `BLOCKS_PER_TIER`
// blocks regardless of how wide that tier is in raw % terms.
const fillCount = computed(() => {
  const v = clampedPct.value;
  const normal = Math.max(0, Math.min(100, props.normalThresholdPct));
  const critical = Math.max(normal, Math.min(100, props.criticalThresholdPct));
  if (v <= 0) return 0;
  if (v < normal) return Math.floor((v / normal) * BLOCKS_PER_TIER);
  if (v < critical) return LOW_END_BLOCK + Math.floor(((v - normal) / (critical - normal)) * BLOCKS_PER_TIER);
  if (critical >= 100) return BLOCK_COUNT;
  return MEDIUM_END_BLOCK + Math.floor(((v - critical) / (100 - critical)) * BLOCKS_PER_TIER);
});

const blocks = computed<Block[]>(() => {
  const out: Block[] = [];
  for (let i = 1; i <= BLOCK_COUNT; i++) {
    let fillColor: string;
    let hollowColor: string;
    if (i <= LOW_END_BLOCK) {
      fillColor = GREEN_FILL;
      hollowColor = GREEN_HOLLOW;
    } else if (i <= MEDIUM_END_BLOCK) {
      fillColor = AMBER_FILL;
      hollowColor = AMBER_HOLLOW;
    } else {
      fillColor = RED_FILL;
      hollowColor = RED_HOLLOW;
    }
    out.push({ idx: i, fill: i <= fillCount.value, fillColor, hollowColor });
  }
  return out;
});

const formattedValue = computed(() =>
  typeof props.value === 'number' && !Number.isNaN(props.value) ? `${clampedPct.value.toFixed(1)}%` : '—'
);
</script>
