<template>
  <Card v-if="streaks.length" data-testid="workshift-streaks" class="shadow-none">
    <CardHeader>
      <CardTitle class="flex items-center gap-2 text-base">
        <RepeatIcon class="size-4 text-muted-foreground" aria-hidden="true" />
        Response Streaks
        <span class="tabular-nums text-muted-foreground">({{ streaks.length }})</span>
      </CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-2">
      <div v-for="(s, i) in streaks" :key="streakKey(s)" class="rounded-md border border-border">
        <button
          type="button"
          data-testid="streak-row"
          class="flex w-full flex-wrap items-center gap-x-3 gap-y-1 px-3 py-2.5 text-left transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-foreground/20"
          :aria-expanded="expandedIndex === i"
          @click="toggleExpanded(i)"
        >
          <ChevronRightIcon
            class="size-4 shrink-0 text-muted-foreground transition-transform"
            :class="expandedIndex === i ? 'rotate-90' : ''"
            aria-hidden="true"
          />
          <span
            :class="[
              'rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase',
              STREAK_SEVERITY_BADGE_CLASS[s.severity],
            ]"
          >
            {{ s.severity }}
          </span>
          <span class="text-sm font-medium">{{ s.type }}</span>
          <span class="text-xs tabular-nums text-muted-foreground">×{{ s.length }}</span>
          <span class="text-xs tabular-nums text-muted-foreground">
            {{ formatStatsRowClockTime(s.startTime) }} – {{ formatStatsRowClockTime(s.endTime) }}
          </span>
          <span
            v-if="s.startAddress"
            class="hidden max-w-[16rem] truncate text-xs text-muted-foreground sm:block"
            :title="s.startAddress"
          >
            {{ s.startAddress }}
          </span>
          <span class="ml-auto text-xs tabular-nums text-muted-foreground"> {{ membersByIndex[i].length }} shown </span>
        </button>

        <div v-if="expandedIndex === i" class="border-t border-border p-2">
          <p v-if="!membersByIndex[i].length" class="px-1 py-1 text-xs text-muted-foreground">
            No matching interactions found in this window.
          </p>
          <ul v-else class="flex flex-col gap-1">
            <li v-for="m in membersByIndex[i]" :key="`${m.id ?? m.ts}`">
              <button
                type="button"
                data-testid="streak-member-row"
                :disabled="m.id == null"
                :aria-current="m.id != null && m.id === selectedInteractionId ? 'true' : undefined"
                class="flex w-full flex-wrap items-center gap-x-2 gap-y-1 rounded border px-2 py-1.5 text-left text-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500 disabled:cursor-default"
                :class="
                  m.id != null && m.id === selectedInteractionId
                    ? 'border-red-500 bg-red-50 ring-1 ring-red-500 dark:bg-red-950/40'
                    : 'border-border enabled:hover:bg-muted/60'
                "
                @click="onMemberClick(m)"
              >
                <span class="text-muted-foreground">#{{ m.id != null ? m.id + 1 : '?' }}</span>
                <span class="text-muted-foreground">·</span>
                <span class="tabular-nums">{{ formatStatsRowClockTime(m.ts) }}</span>
                <span class="text-muted-foreground">·</span>
                <span class="inline-flex items-center gap-1.5">
                  <span
                    v-if="m.response_color"
                    class="size-2 rounded-full"
                    :style="{ backgroundColor: m.response_color }"
                    aria-hidden="true"
                  />
                  {{ formatResponseLabel(m.response) }}
                </span>
                <span v-for="reason in m.app_flag_reasons ?? []" :key="reason" :class="APP_FLAG_REASON_CHIP_CLASS">
                  {{ reason }}
                </span>
              </button>
            </li>
          </ul>
        </div>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { ChevronRightIcon, RepeatIcon } from 'lucide-vue-next';
import type { CanvassingAppFlags, InteractionPointView } from '~/client';
import {
  APP_FLAG_REASON_CHIP_CLASS,
  buildStreakRows,
  formatStatsRowClockTime,
  STREAK_SEVERITY_BADGE_CLASS,
  streakMemberInteractions,
  type StreakRow,
} from '~/constants/workshifts/canvassingAppStatsConfig';
import { formatResponseLabel } from '~/utils/canvassing/format';

interface Props {
  flags: CanvassingAppFlags;
  interactions?: InteractionPointView[];
  selectedInteractionId?: number | null;
}
const props = withDefaults(defineProps<Props>(), {
  interactions: () => [],
  selectedInteractionId: null,
});

const emit = defineEmits<{
  // Emitted when a member row is clicked — the page selects it on the map and
  // scrolls it into view. Null toggles the current selection off.
  select: [id: number | null];
}>();

const streaks = computed(() => buildStreakRows(props.flags));

function streakKey(s: StreakRow): string {
  return `${s.type}-${s.startTime ?? ''}-${s.endTime ?? ''}-${s.length}`;
}
const membersByIndex = computed(() => streaks.value.map((s) => streakMemberInteractions(s, props.interactions)));

const expandedIndex = ref<number | null>(null);
function toggleExpanded(i: number) {
  expandedIndex.value = expandedIndex.value === i ? null : i;
}

watch(streaks, () => {
  expandedIndex.value = null;
});

function onMemberClick(m: InteractionPointView) {
  if (m.id == null) return;
  emit('select', m.id === props.selectedInteractionId ? null : m.id);
}
</script>
