<template>
  <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
    <ReportFraudReportCard
      v-for="card in cards"
      :key="card.key"
      :title="card.title"
      :icon="card.icon"
      :severity="card.severity"
      :headline="card.headline"
      :subtitle="card.subtitle"
      :anomaly-bars="card.anomalyBars"
      :extras="card.extras"
      :speed-gauge="card.speedGauge"
      :flagged-interactions="card.flaggedInteractions"
      :selected-interaction-id="selectedInteractionId"
      :flag-filter="flagFilter ?? null"
      :class="
        card.key === 'engagement' && (card.flaggedInteractions?.length ?? 0) > 0 ? 'md:col-span-2 xl:col-span-3' : ''
      "
      @update:selected-interaction-id="(v: number | null) => emit('update:selectedInteractionId', v)"
      @request-focus-map="emit('request-focus-map')"
    />
  </div>
</template>

<script setup lang="ts">
import type { InteractionPointView, RenderedReport } from '~/client';
import { buildReportCards } from '~/constants/reports/fraudReportCards';
import type { RowFlagKey } from '~/constants/workshifts/canvassingAppStatsConfig';

interface Props {
  stats: RenderedReport;
  interactions?: InteractionPointView[];
  selectedInteractionId?: number | null;
  flagFilter?: RowFlagKey | null;
}
const props = defineProps<Props>();

const emit = defineEmits<{
  'update:selectedInteractionId': [id: number | null];
  'request-focus-map': [];
}>();

const cards = computed(() => buildReportCards(props.stats, props.interactions));
</script>
