type DefinedKeys<T> = {
  [K in keyof T]-?: Exclude<T[K], undefined> extends never ? never : K;
}[keyof T];

export interface FraudPlotEntry {
  key: DefinedKeys<ReportPlotPublicUrls>;
  title: string;
}

