export function formatFraudKpiValue(raw: unknown, unit: FraudKpiTile['unit']): string {
  if (raw === null || raw === undefined || raw === '') return '—';
  if (unit === 'bool') return raw ? 'Yes' : 'No';
  if (typeof raw !== 'number') return String(raw);
  if (Number.isNaN(raw)) return '—';

  switch (unit) {
    case 'percent':
      return `${raw.toFixed(1)}%`;
    case 'seconds':
      return formatSecondsHuman(raw);
    case 'meters':
      return raw >= 1000 ? `${(raw / 1000).toFixed(2)} km` : `${raw.toFixed(0)} m`;
    case 'mps':
      return `${raw.toFixed(2)} m/s`;
    case 'count':
      return Number.isInteger(raw) ? raw.toString() : raw.toFixed(0);
    default:
      return raw.toFixed(2);
  }
}
