<template>
  <section class="grid grid-cols-2 gap-6">
    <PageTitle title="Report Details" class="col-span-2" />
    <div class="col-span-2 flex flex-wrap justify-between items-center gap-4">
      <div />
      <div class="flex items-center gap-2">
        <Badge v-if="statusBadge" :variant="statusBadge.variant">
          {{ statusBadge.label }}
        </Badge>
        <template v-if="report?.review_status">
          <Badge :variant="getReportReviewStatusBadge(report.review_status).variant">
            {{ getReportReviewStatusBadge(report.review_status).label }}
          </Badge>
        </template>
      </div>
    </div>

    <AppLoader v-if="isLoading" class="col-span-2" subject="report details" />
    <AppError v-else-if="error" :error="error" title="Failed to load report details" class="col-span-2" />
    <AppEmpty v-else-if="!report" class="col-span-2" subject="report details" />

    <template v-else>
      <Alert
        v-if="report.review_status === 'confirmed' && report.reviewed_details"
        variant="success"
        class="col-span-2"
      >
        <CircleCheckIcon />
        <AlertTitle>Confirmed</AlertTitle>
        <AlertDescription>
          This report was confirmed by
          <InlineEntityUser :user-id="report.reviewed_details.user_id" /> on
          {{ formatDateBasedOnType(report.reviewed_details.timestamp, timezone) }}.
        </AlertDescription>
      </Alert>

      <Alert
        v-if="report.review_status === 'discarded' && report.reviewed_details"
        variant="destructive"
        class="col-span-2"
      >
        <TriangleAlertIcon />
        <AlertTitle>Discarded</AlertTitle>
        <AlertDescription>
          This report was discarded by
          <InlineEntityUser :user-id="report.reviewed_details.user_id" /> on
          {{ formatDateBasedOnType(report.reviewed_details.timestamp, timezone) }}.
        </AlertDescription>
      </Alert>

      <Card class="col-span-2">
        <CardContent class="flex flex-col gap-4">
          <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 sm:gap-4">
            <LabeledEntityUser :user-id="report.canvasser_id" />
            <LabeledEntityProject v-if="report.project_id" :project-id="report.project_id" />
            <LabeledEntityWorkShift v-if="report.work_shift_id" :work-shift-id="report.work_shift_id" />
            <LabeledEntityDate label="Created At" :date="report.created_at" />
            <LabeledValueIcon label="Type" :icon="FileTextIcon"
              ><span class="capitalize">{{ report.type }}</span></LabeledValueIcon
            >
          </div>
        </CardContent>
      </Card>

      <Card v-if="report.state === 'failed'" class="col-span-2">
        <CardContent class="pt-6 text-sm text-muted-foreground">
          <template v-if="report.failure_reason === 'no_data'">
            No location or interaction data was recorded for this work shift, so there was nothing to analyze.
          </template>
          <template v-else> This report could not be generated due to a processing error. </template>
        </CardContent>
      </Card>

      <Card v-if="report.pdf_state === 'ready' && report.pdf_url" class="col-span-2">
        <CardHeader>
          <CardTitle>PDF Report</CardTitle>
        </CardHeader>
        <CardContent>
          <a :href="report.pdf_url" target="_blank" rel="noopener noreferrer">
            <Button variant="outline" :prepend-icon="DownloadIcon"> Download PDF </Button>
          </a>
        </CardContent>
      </Card>

      <ReportFraudScoreHeader
        v-if="isFraudReady && viewData"
        :final-score="viewData.final_score"
        :stats="viewData.stats"
        class="col-span-2"
      />

      <AppLoader
        v-if="isFraudReady && isViewDataLoading && !viewData"
        class="col-span-2"
        variant="inline"
        subject="report data"
      />
      <ReportFraudDetailsPlaceholder
        v-else-if="isFraudReady && isViewDataNotReady"
        state="pending"
        class="col-span-2"
      />
      <AppError
        v-else-if="isFraudReady && viewDataError"
        :error="viewDataError"
        title="Failed to load report data"
        variant="table"
        class="col-span-2"
      />
      <ReportFraudDetails
        v-else-if="isFraudReady && viewData"
        :view-data="viewData"
        :is-detailed="isDetailed"
        :is-fetching="isViewDataFetching"
        class="col-span-2"
        @toggle-detailed-route="toggleSimplified"
      />
      <ReportFraudDetailsPlaceholder
        v-else-if="report.type === 'canvassing' && report.view_data_state && report.view_data_state !== 'ready'"
        :state="report.view_data_state"
        class="col-span-2"
      />

      <div v-if="report.review_status === 'pending'" class="col-span-2 flex gap-4 justify-end">
        <ConfirmationDialog
          title="Confirm report?"
          description="Are you sure you want to confirm this report? This action cannot be undone."
          confirm-btn-text="Confirm"
          :is-confirm-loading="isConfirmingReport"
          @confirm="onConfirm"
        >
          <Button>Confirm</Button>
        </ConfirmationDialog>
        <ConfirmationDialog
          title="Discard report?"
          description="Are you sure you want to discard this report? This action cannot be undone."
          confirm-btn-text="Discard"
          confirm-btn-variant="destructive"
          :is-confirm-loading="isDiscardingReport"
          @confirm="onDiscard"
        >
          <Button variant="destructive">Discard</Button>
        </ConfirmationDialog>
      </div>
    </template>
  </section>
</template>

<script setup lang="ts">
import { TriangleAlertIcon, CircleCheckIcon, DownloadIcon, FileTextIcon } from 'lucide-vue-next';
import { FetchError } from 'ofetch';
import { getReportDetails } from '~/client';
import { useConfirmReport } from '~/mutations/reports/confirm';
import { useDiscardReport } from '~/mutations/reports/discard';
import { resolveReportStatusBadge } from '~/constants/reports/reportStatuses';
import { getReportReviewStatusBadge } from '~/constants/reports/reportReviewStatusConfig';
import { formatDateBasedOnType } from '~/utils/formatDateToFormat';
import { useReportViewDataQuery } from '~/queries/reports/viewData';
import { useSimplifiedRoute } from '~/composables/useSimplifiedRoute';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'report',
});

useHead({
  title: 'Report Details',
});

const route = useRoute('reports-id');
const id = computed(() => route.params.id?.toString());

const {
  data: report,
  error,
  isLoading,
  refetch: refetchReport,
} = useQuery({
  key: () => ['report-details', id.value],
  query: () => getReportDetails({ composable: '$fetch', path: { report_id: id.value as string } }),
  staleTime: 0,
  enabled: () => Boolean(id.value) && route.name === 'reports-id',
});

const isFraudReady = computed(() =>
  Boolean(report.value && report.value.type === 'canvassing' && report.value.view_data_state === 'ready')
);

const statusBadge = computed(() =>
  report.value ? resolveReportStatusBadge(report.value.state, report.value.failure_reason) : null
);

const { simplified, isDetailed, toggle: toggleSimplified } = useSimplifiedRoute();

const {
  data: viewData,
  error: viewDataError,
  isLoading: isViewDataLoading,
  asyncStatus: viewDataAsyncStatus,
} = useReportViewDataQuery(id, isFraudReady, simplified);

const isViewDataFetching = computed(() => viewDataAsyncStatus.value === 'loading');

const isViewDataNotReady = computed(() => {
  const err = viewDataError.value;
  return err instanceof FetchError && err.statusCode === 409;
});

watch(isViewDataNotReady, (notReady) => {
  if (notReady) refetchReport();
});

const { confirmReportMutation, isConfirmingReport } = useConfirmReport();
const { discardReportMutation, isDiscardingReport } = useDiscardReport();
const { timezone } = useUserRole();

async function onConfirm() {
  if (!id.value) return;
  await confirmReportMutation(id.value);
}

async function onDiscard() {
  if (!id.value) return;
  await discardReportMutation(id.value);
}
</script>
