<template>
  <div v-if="visiblePlots.length" class="grid grid-cols-1 md:grid-cols-2 gap-4">
    <Card v-for="plot in visiblePlots" :key="plot.key">
      <CardHeader>
        <CardTitle class="text-sm font-medium">{{ plot.title }}</CardTitle>
      </CardHeader>
      <CardContent>
        <a :href="plot.url" target="_blank" rel="noopener noreferrer" class="block">
          <img :src="plot.url" :alt="plot.title" class="w-full h-auto rounded-sm" />
        </a>
      </CardContent>
    </Card>
  </div>
</template>

<script setup lang="ts">
import type { ReportPlotPublicUrls } from '~/client';
import { fraudStaticPlots } from '~/constants/reports/fraudKpiConfig';

interface Props {
  plotUrls: ReportPlotPublicUrls;
}
const props = defineProps<Props>();

const visiblePlots = computed(() =>
  fraudStaticPlots
    .map((entry) => ({ ...entry, url: props.plotUrls[entry.key] }))
    .filter((p): p is { key: typeof p.key; title: string; url: string } => Boolean(p.url))
);
</script>
