<template>
  <Card :class="['border-l-4', severityStyle.borderClass, 'h-full']">
    <CardHeader class="pb-3">
      <div class="flex items-start justify-between gap-3">
        <div class="flex items-center gap-2 min-w-0">
          <component :is="icon" class="size-5 shrink-0 text-muted-foreground" />
          <CardTitle class="text-base truncate">{{ title }}</CardTitle>
        </div>
        <span :class="['rounded-full px-2.5 py-0.5 text-xs font-medium whitespace-nowrap', severityStyle.chipClass]">
          {{ severityStyle.label }}
        </span>
      </div>
    </CardHeader>
    <CardContent class="flex flex-col gap-3">
      <p class="text-lg font-semibold leading-tight">{{ headline }}</p>
      <p class="text-sm text-muted-foreground">{{ subtitle }}</p>

      <!-- NEW: flagged interactions list (only on engagement card when populated) -->
      <ReportFraudEngagementList
        v-if="flaggedInteractions && flaggedInteractions.length"
        class="pt-2"
        :interactions="flaggedInteractions"
        :selected-interaction-id="selectedInteractionId ?? null"
        :flag-filter="flagFilter ?? null"
        @update:selected-interaction-id="(v: number | null) => emit('update:selectedInteractionId', v)"
        @request-focus-map="emit('request-focus-map')"
      />

      <SpeedRangeGauge v-if="speedGauge" class="pt-1" :avg="speedGauge.avg" :top="speedGauge.top" />

      <div v-if="anomalyBars && anomalyBars.length" class="flex flex-col gap-3 pt-1">
        <ReportFraudIssueScale
          v-for="bar in anomalyBars"
          :key="bar.title"
          :title="bar.title"
          :description="bar.description"
          :value="bar.value"
          :normal-threshold-pct="ANOMALY_BAR_NORMAL_PCT"
          :critical-threshold-pct="ANOMALY_BAR_CRITICAL_PCT"
        />
      </div>

      <dl v-if="extras && extras.length" class="flex flex-col gap-1 pt-1 text-sm">
        <div v-for="extra in extras" :key="extra.label" class="flex items-center justify-between gap-3">
          <dt class="text-muted-foreground">{{ extra.label }}</dt>
          <dd class="font-medium tabular-nums truncate text-right">{{ extra.value }}</dd>
        </div>
      </dl>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { Component } from 'vue';
import type { InteractionPointView } from '~/client';
import type {
  FraudAnomalyBar,
  FraudCardExtra,
  FraudSeverity,
  FraudSpeedGauge,
} from '~/constants/reports/fraudReportCards';
import type { RowFlagKey } from '~/constants/workshifts/canvassingAppStatsConfig';
import {
  ANOMALY_BAR_CRITICAL_PCT,
  ANOMALY_BAR_NORMAL_PCT,
  getFraudSeverityStyle,
} from '~/constants/reports/fraudReportCards';

interface Props {
  title: string;
  icon: Component;
  severity: FraudSeverity;
  headline: string;
  subtitle: string;
  anomalyBars?: FraudAnomalyBar[];
  extras?: FraudCardExtra[];
  speedGauge?: FraudSpeedGauge;
  flaggedInteractions?: InteractionPointView[];
  selectedInteractionId?: number | null;
  flagFilter?: RowFlagKey | null;
}
const props = defineProps<Props>();

const emit = defineEmits<{
  'update:selectedInteractionId': [id: number | null];
  'request-focus-map': [];
}>();

const severityStyle = computed(() => getFraudSeverityStyle(props.severity));
</script>
