import { discardReport } from '~/client';

export const useDiscardReport = defineMutation(() => {
  const { mutateAsync: discardReportMutation, asyncStatus } = useMutation({
    mutation: (reportId: string) =>
      discardReport({
        composable: '$fetch',
        path: { report_id: reportId },
      }),
    onSuccess: async (_, reportId) => {
      showToastSuccess('Report discarded successfully.');
      const queryCache = useQueryCache();
      await queryCache.invalidateQueries({ key: ['report-details', reportId] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    discardReportMutation,
    isDiscardingReport: computed(() => asyncStatus.value === 'loading'),
  };
});
