<template>
  <div class="flex flex-col gap-6">
    <div ref="mapCardRef">
      <Card>
        <CardHeader>
          <div class="flex flex-wrap items-center justify-between gap-2">
            <CardTitle>Route &amp; Interactions</CardTitle>
            <div v-if="totalSegments > 0" class="flex items-center gap-3 text-sm text-muted-foreground">
              <span v-if="viewData.route_segments_simplified">
                Showing {{ routeSegments.length }} of {{ totalSegments }} segments
              </span>
              <span v-else>Showing all {{ totalSegments }} segments</span>
              <Button
                variant="outline"
                size="sm"
                :prepend-icon="isDetailed ? MinimizeIcon : MaximizeIcon"
                :disabled="isFetching"
                @click="emit('toggle-detailed-route')"
              >
                {{ isDetailed ? 'Show Simplified Route' : 'Show Detailed Route' }}
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <CanvassingMap
            v-if="canRenderMap && !mapErrored"
            v-model:selected-interaction-id="selectedInteractionId"
            :route-segments="routeSegments"
            :interactions="interactions"
            :motion-activity-segments="motionActivitySegments"
            :pause-intervals="pauseIntervals"
            :map-bounds="viewData.map_bounds ?? null"
            show-app-flags
          />
          <ReportFraudMapFallback
            v-else
            :route-map-url="viewData.plot_urls?.route_map_plot ?? null"
            :interactions-map-url="viewData.plot_urls?.interactions_map_plot ?? null"
          />
        </CardContent>
      </Card>
    </div>

    <ReportFraudVerdictCard :stats="viewData.stats" />

    <WorkshiftStatisticsFlags v-if="appFlags" v-model:selected-flag="selectedFlag" :flags="appFlags" selectable />

    <ReportFraudReportCards
      v-model:selected-interaction-id="selectedInteractionId"
      :stats="viewData.stats"
      :interactions="interactions"
      :flag-filter="selectedFlag"
      @request-focus-map="scrollMapIntoView"
    />

    <WorkshiftStreaks
      v-if="appFlags"
      :flags="appFlags"
      :interactions="interactions"
      :selected-interaction-id="selectedInteractionId"
      @select="onAppFlagSelect"
    />

    <details class="rounded-md border border-border bg-card">
      <summary class="cursor-pointer select-none px-4 py-3 text-sm font-medium hover:bg-muted/50">
        Detailed metrics
      </summary>
      <div class="border-t border-border p-4">
        <ReportFraudKpiGrid :stats="viewData.stats" />
      </div>
    </details>

    <ReportFraudPlotGrid :plot-urls="viewData.plot_urls" />

    <ReportFraudMotionPlots :motion-sensor-plot-urls="viewData.motion_sensor_plot_urls" />
  </div>
</template>

<script setup lang="ts">
import { MaximizeIcon, MinimizeIcon } from 'lucide-vue-next';
import type { GetCanvassingFraudReportViewDataResponse } from '~/client';
import type { RowFlagKey } from '~/constants/workshifts/canvassingAppStatsConfig';

interface Props {
  viewData: GetCanvassingFraudReportViewDataResponse;
  isDetailed: boolean;
  isFetching: boolean;
}
const props = defineProps<Props>();

const emit = defineEmits<{
  'toggle-detailed-route': [];
}>();

const routeSegments = computed(() => props.viewData.route_segments ?? []);
const interactions = computed(() => props.viewData.interactions ?? []);
const pauseIntervals = computed(() => props.viewData.pause_intervals ?? []);
const motionActivitySegments = computed(() => props.viewData.motion_activity_segments ?? []);
const totalSegments = computed(() => props.viewData.route_segments_total ?? 0);

const canRenderMap = computed(() => routeSegments.value.length > 0 || interactions.value.length > 0);

const selectedInteractionId = ref<number | null>(null);
const selectedFlag = ref<RowFlagKey | null>(null);
const mapCardRef = ref<HTMLDivElement | null>(null);

function scrollMapIntoView() {
  mapCardRef.value?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

const appFlags = computed(() => props.viewData.app_flags ?? null);

function onAppFlagSelect(id: number | null) {
  selectedInteractionId.value = id;
  if (id != null) scrollMapIntoView();
}

const mapErrored = ref(false);
watch(
  () => props.viewData,
  () => {
    mapErrored.value = false;
  }
);

onErrorCaptured((err, instance) => {
  const isMap = instance?.$options?.__name === 'CanvassingMap';
  if (!isMap) return undefined;
  mapErrored.value = true;
  console.error('[CanvassingMap] failed to render, falling back to static images', err);
  return false;
});
</script>
