import type { InteractionPointView } from '~/client';
import { fraudSeverityConfig } from '~/constants/reports/fraudReportCards';

export type FlaggedInteractionsSortMode = 'severity' | 'time';

function timeAsc(a: InteractionPointView, b: InteractionPointView): number {
  return Date.parse(a.ts) - Date.parse(b.ts);
}

function timeDesc(a: InteractionPointView, b: InteractionPointView): number {
  return -timeAsc(a, b);
}

function severityRank(item: InteractionPointView): number {
  const sev = item.fraud?.severity;
  if (!sev) return -1;
  return fraudSeverityConfig[sev].rank;
}

export function sortFlaggedInteractions(
  items: InteractionPointView[],
  mode: FlaggedInteractionsSortMode
): InteractionPointView[] {
  const copy = [...items];
  if (mode === 'time') {
    // Newest first — gives a visibly different order from severity mode even when
    // every item shares the same severity (severity mode ties-breaks on time ASC).
    copy.sort(timeDesc);
    return copy;
  }
  // severity desc, ties broken by time asc
  copy.sort((a, b) => {
    const rDelta = severityRank(b) - severityRank(a);
    if (rDelta !== 0) return rDelta;
    return timeAsc(a, b);
  });
  return copy;
}
