<template>
  <Card class="overflow-hidden">
    <div class="border-l-8" :style="{ borderColor: severityColor }">
      <CardContent class="flex flex-col md:flex-row md:items-center gap-6 py-5">
        <div
          class="relative shrink-0 w-28 h-28"
          role="img"
          :aria-label="`Risk score: ${scorePercent}, ${severityLabel}`"
        >
          <svg viewBox="0 0 120 120" class="w-28 h-28 -rotate-90" aria-hidden="true">
            <circle cx="60" cy="60" r="50" fill="none" stroke="currentColor" stroke-width="10" class="text-muted/30" />
            <circle
              cx="60"
              cy="60"
              r="50"
              fill="none"
              :stroke="severityColor"
              stroke-width="10"
              stroke-linecap="round"
              :stroke-dasharray="strokeDasharray"
              class="transition-all duration-500 ease-out"
            />
          </svg>
          <div class="absolute inset-0 flex flex-col items-center justify-center">
            <span class="text-2xl font-bold tabular-nums leading-none">{{ scorePercent }}</span>
            <span class="mt-1 text-[10px] uppercase tracking-wider text-muted-foreground">Risk score</span>
          </div>
        </div>

        <div class="flex flex-col gap-1 min-w-0">
          <span class="text-3xl font-bold capitalize" :style="{ color: severityColor }">
            {{ severityLabelDisplay }}
          </span>
        </div>

        <div class="flex flex-col gap-2 flex-1 md:max-w-md md:ml-auto">
          <div class="text-xs uppercase tracking-wider text-muted-foreground">Risk spectrum</div>
          <div class="relative h-3 rounded-full" :style="{ background: spectrumGradient }">
            <div
              class="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-5 h-5 rounded-full bg-white border-[3px] shadow-md transition-all duration-500 ease-out"
              :style="{ left: `${markerPosition}%`, borderColor: severityColor }"
              :title="`${scorePercent} — ${severityLabel}`"
            />
          </div>
          <div class="flex justify-between text-xs text-muted-foreground">
            <span>Low</span>
            <span>Medium</span>
            <span>High</span>
          </div>
        </div>
      </CardContent>
    </div>
  </Card>
</template>

<script setup lang="ts">
import type { RenderedReport } from '~/client';
import { fraudScoreBand } from '~/constants/reports/fraudScoreBands';

interface Props {
  finalScore: number;
  stats: RenderedReport;
}
const props = defineProps<Props>();

const RADIUS = 50;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

const clampedScore = computed(() => {
  const s = props.finalScore;
  if (!Number.isFinite(s)) return 0;
  return Math.max(0, Math.min(100, s));
});
const scorePercent = computed(() => `${clampedScore.value.toFixed(0)}%`);
const arcLength = computed(() => (clampedScore.value / 100) * CIRCUMFERENCE);
const strokeDasharray = computed(() => `${arcLength.value.toFixed(2)} ${CIRCUMFERENCE.toFixed(2)}`);
const markerPosition = computed(() => clampedScore.value);

const band = computed(() => fraudScoreBand(props.finalScore));
const severityLabel = computed(() => props.stats.severity_label || band.value.label);
const severityLabelDisplay = computed(() => severityLabel.value.toLowerCase());
const severityColor = computed(() => props.stats.severity_label_color || band.value.color);

const spectrumGradient =
  'linear-gradient(to right, hsl(120, 65%, 45%), hsl(60, 70%, 50%), hsl(30, 80%, 50%), hsl(0, 80%, 45%))';
</script>
